using Astronomy.MediaFactory.Core.DocumentaryBlueprint;
namespace Astronomy.MediaFactory.Tests.DocumentaryBlueprint; public sealed class DocumentaryMediaProjectionContractTests { [Fact] public void Public_contracts_are_closed_immutable_property_bags(){Type[] types=[typeof(DocumentaryMediaProjectionPolicy),typeof(DocumentaryMediaProjectionMetadata),typeof(DocumentaryAstronomyTopicProfile),typeof(DocumentaryMediaProjectionRequest),typeof(DocumentaryMediaKnowledgeReference),typeof(DocumentaryNarrationBlock),typeof(DocumentarySubtitleCue),typeof(DocumentaryVisualPrompt),typeof(DocumentarySceneTiming),typeof(DocumentaryMediaScene),typeof(DocumentaryMediaVariant),typeof(DocumentaryMediaProject),typeof(DocumentaryMediaProjectionResult),typeof(DocumentaryMediaProjectionSummary)];Assert.All(types,t=>{Assert.True(t.IsPublic&&t.IsSealed);Assert.NotEmpty(t.GetProperties());Assert.All(t.GetProperties(),p=>Assert.False(p.SetMethod?.IsPublic??false));});} [Fact] public void Constructors_reject_null_root_values(){Assert.Throws<ArgumentNullException>(()=>new DocumentaryMediaProjector().Project(null!));Assert.Throws<ArgumentNullException>(()=>new DocumentaryMediaProjectionSummarizer().Summarize(null!));} }
